#define _GNU_SOURCE
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <unistd.h>
#include <sched.h>

#ifdef __AVX512F__
#define VW 16
#else
#define VW 8
#endif
#define MR 6
#define NR (2 * VW)
#define KC 256
#define MAXT 64
#define SPIN_LIMIT 200000

typedef float vf __attribute__((vector_size(VW * 4)));

static inline vf ldu(const float *p) { vf v; memcpy(&v, p, sizeof v); return v; }
static inline void stu(float *p, vf v) { memcpy(p, &v, sizeof v); }

static inline void cpu_relax(void)
{
#if defined(__x86_64__) || defined(__i386__)
    __builtin_ia32_pause();
#elif defined(__aarch64__)
    __asm__ __volatile__("yield");
#endif
}

/* Computes (or accumulates into) an mr x nr tile of C from packed A and B panels. */
static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int mr, int nr, int acc)
{
    vf c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    vf c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

    for (int i = 0; i < mr; i++) {
        __builtin_prefetch(c + (size_t)i * ldc, 1, 3);
        __builtin_prefetch(c + (size_t)i * ldc + NR - 1, 1, 3);
    }

#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        vf b0 = *(const vf *)(b);
        vf b1 = *(const vf *)(b + VW);
        float a0 = a[0], a1 = a[1], a2 = a[2], a3 = a[3], a4 = a[4], a5 = a[5];
        c00 += a0 * b0; c01 += a0 * b1;
        c10 += a1 * b0; c11 += a1 * b1;
        c20 += a2 * b0; c21 += a2 * b1;
        c30 += a3 * b0; c31 += a3 * b1;
        c40 += a4 * b0; c41 += a4 * b1;
        c50 += a5 * b0; c51 += a5 * b1;
        a += MR;
        b += NR;
    }

    vf r[MR][2] = {{c00, c01}, {c10, c11}, {c20, c21},
                   {c30, c31}, {c40, c41}, {c50, c51}};

    if (mr == MR && nr == NR) {
        for (int i = 0; i < MR; i++) {
            float *cp = c + (size_t)i * ldc;
            if (acc) {
                stu(cp, ldu(cp) + r[i][0]);
                stu(cp + VW, ldu(cp + VW) + r[i][1]);
            } else {
                stu(cp, r[i][0]);
                stu(cp + VW, r[i][1]);
            }
        }
    } else {
        float tmp[MR][NR];
        for (int i = 0; i < MR; i++) {
            memcpy(&tmp[i][0], &r[i][0], sizeof(vf));
            memcpy(&tmp[i][VW], &r[i][1], sizeof(vf));
        }
        for (int i = 0; i < mr; i++) {
            float *cp = c + (size_t)i * ldc;
            if (acc)
                for (int j = 0; j < nr; j++) cp[j] += tmp[i][j];
            else
                for (int j = 0; j < nr; j++) cp[j] = tmp[i][j];
        }
    }
}

/* Packs MR rows starting at ip for all k blocks. Layout: Ap[pc*Mp + ip*kc + k*MR + r]. */
static void pack_a_panel(const float *A, int n, int Mp, int ip, float *Ap)
{
    int rows = n - ip < MR ? n - ip : MR;
    for (int pc = 0; pc < n; pc += KC) {
        int kc = n - pc < KC ? n - pc : KC;
        float *d = Ap + (size_t)pc * Mp + (size_t)ip * kc;
        const float *s = A + (size_t)ip * n + pc;
        if (rows == MR) {
            const float *s0 = s, *s1 = s + n, *s2 = s + 2 * (size_t)n;
            const float *s3 = s + 3 * (size_t)n, *s4 = s + 4 * (size_t)n, *s5 = s + 5 * (size_t)n;
            for (int k = 0; k < kc; k++) {
                d[0] = s0[k]; d[1] = s1[k]; d[2] = s2[k];
                d[3] = s3[k]; d[4] = s4[k]; d[5] = s5[k];
                d += MR;
            }
        } else {
            for (int k = 0; k < kc; k++) {
                int r = 0;
                for (; r < rows; r++) d[r] = s[(size_t)r * n + k];
                for (; r < MR; r++) d[r] = 0.0f;
                d += MR;
            }
        }
    }
}

/* Packs rows [k0, k1) of B. Layout: Bp[pc*Np + jp*kc + kk*NR + j]. */
static void pack_b_rows(const float *B, int n, int Np, int k0, int k1, float *Bp)
{
    for (int k = k0; k < k1; k++) {
        int pc = k / KC * KC;
        int kc = n - pc < KC ? n - pc : KC;
        int kk = k - pc;
        const float *s = B + (size_t)k * n;
        float *d = Bp + (size_t)pc * Np + (size_t)kk * NR;
        int jp = 0;
        for (; jp + NR <= n; jp += NR)
            memcpy(d + (size_t)jp * kc, s + jp, NR * sizeof(float));
        if (jp < n) {
            float *dd = d + (size_t)jp * kc;
            int c = n - jp;
            memcpy(dd, s + jp, (size_t)c * sizeof(float));
            memset(dd + c, 0, (size_t)(NR - c) * sizeof(float));
        }
    }
}

typedef struct {
    const float *A, *B;
    float *C, *Ap, *Bp;
    int n, Mp, Np, nt;
    int tile_m, tile_n, tiles_n, ntiles;
    int next;
    int bar_count, bar_gen;
} job_t;

static job_t g_job;

static void barrier_wait(job_t *j)
{
    int g = __atomic_load_n(&j->bar_gen, __ATOMIC_ACQUIRE);
    if (__atomic_add_fetch(&j->bar_count, 1, __ATOMIC_ACQ_REL) == j->nt) {
        __atomic_store_n(&j->bar_count, 0, __ATOMIC_RELAXED);
        __atomic_store_n(&j->bar_gen, g + 1, __ATOMIC_RELEASE);
    } else {
        long spins = 0;
        while (__atomic_load_n(&j->bar_gen, __ATOMIC_ACQUIRE) == g) {
            cpu_relax();
            if (++spins > (1 << 16)) { sched_yield(); spins = 0; }
        }
    }
}

static void compute_tile(job_t *j, int t)
{
    int n = j->n, Mp = j->Mp, Np = j->Np;
    int ti = t / j->tiles_n, tj = t % j->tiles_n;
    int i0 = ti * j->tile_m, i1 = i0 + j->tile_m;
    int j0 = tj * j->tile_n, j1 = j0 + j->tile_n;
    if (i1 > n) i1 = n;
    if (j1 > n) j1 = n;
    float *C = j->C;

    for (int pc = 0; pc < n; pc += KC) {
        int kc = n - pc < KC ? n - pc : KC;
        int acc = pc != 0;
        const float *ab = j->Ap + (size_t)pc * Mp;
        const float *bb = j->Bp + (size_t)pc * Np;
        for (int jr = j0; jr < j1; jr += NR) {
            int nr = j1 - jr < NR ? j1 - jr : NR;
            const float *bp = bb + (size_t)jr * kc;
            for (int ir = i0; ir < i1; ir += MR) {
                int mr = i1 - ir < MR ? i1 - ir : MR;
                kernel(kc, ab + (size_t)ir * kc, bp, C + (size_t)ir * n + jr, n, mr, nr, acc);
            }
        }
    }
}

static void run(job_t *j, int tid)
{
    int nt = j->nt, n = j->n;

    int npa = j->Mp / MR;
    int pa0 = (int)((long)npa * tid / nt), pa1 = (int)((long)npa * (tid + 1) / nt);
    for (int p = pa0; p < pa1; p++)
        pack_a_panel(j->A, n, j->Mp, p * MR, j->Ap);

    int k0 = (int)((long)n * tid / nt), k1 = (int)((long)n * (tid + 1) / nt);
    pack_b_rows(j->B, n, j->Np, k0, k1, j->Bp);

    if (nt > 1) {
        barrier_wait(j);
        for (;;) {
            int t = __atomic_fetch_add(&j->next, 1, __ATOMIC_RELAXED);
            if (t >= j->ntiles) break;
            compute_tile(j, t);
        }
    } else {
        for (int t = 0; t < j->ntiles; t++) compute_tile(j, t);
    }
}

/* Persistent pool. */
static pthread_mutex_t g_mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t g_cv = PTHREAD_COND_INITIALIZER;
static unsigned g_gen;
static int g_remaining;
static int g_pool = -1;
static int g_hw = 1;

static void *pool_main(void *arg)
{
    int tid = (int)(long)arg;
    unsigned seen = 0;
    for (;;) {
        unsigned g;
        long spins = 0;
        while ((g = __atomic_load_n(&g_gen, __ATOMIC_ACQUIRE)) == seen) {
            if (++spins < SPIN_LIMIT) {
                cpu_relax();
            } else {
                pthread_mutex_lock(&g_mu);
                while (__atomic_load_n(&g_gen, __ATOMIC_ACQUIRE) == seen)
                    pthread_cond_wait(&g_cv, &g_mu);
                pthread_mutex_unlock(&g_mu);
                spins = 0;
            }
        }
        seen = g;
        if (tid < g_job.nt) run(&g_job, tid);
        __atomic_sub_fetch(&g_remaining, 1, __ATOMIC_ACQ_REL);
    }
    return NULL;
}

static int detect_threads(void)
{
    int n = 0;
#ifdef __linux__
    cpu_set_t cs;
    if (sched_getaffinity(0, sizeof cs, &cs) == 0) n = CPU_COUNT(&cs);
#endif
    if (n <= 0) {
        long c = sysconf(_SC_NPROCESSORS_ONLN);
        n = c > 0 ? (int)c : 1;
    }
    int smt = 1;
#ifdef __linux__
    FILE *f = fopen("/sys/devices/system/cpu/cpu0/topology/thread_siblings_list", "r");
    if (f) {
        char buf[256];
        if (fgets(buf, sizeof buf, f)) {
            int count = 0;
            char *p = buf, *e;
            for (;;) {
                long a = strtol(p, &e, 10);
                if (e == p) break;
                long b = a;
                if (*e == '-') b = strtol(e + 1, &e, 10);
                count += (int)(b - a + 1);
                if (*e != ',') break;
                p = e + 1;
            }
            if (count > 1) smt = count;
        }
        fclose(f);
    }
#endif
    if (smt > 1 && n >= smt) n /= smt;
    if (n < 1) n = 1;
    if (n > MAXT) n = MAXT;
    return n;
}

static void pool_init(void)
{
    g_hw = detect_threads();
    int created = 0;
    for (int t = 1; t < g_hw; t++) {
        pthread_t th;
        if (pthread_create(&th, NULL, pool_main, (void *)(long)t) != 0) break;
        pthread_detach(th);
        created++;
    }
    g_pool = created;
}

static float *g_Abuf, *g_Bbuf;
static size_t g_Acap, g_Bcap;

static float *ensure(float **buf, size_t *cap, size_t nfloats)
{
    if (nfloats > *cap) {
        free(*buf);
        size_t bytes = (nfloats * sizeof(float) + 63) / 64 * 64;
        *buf = aligned_alloc(64, bytes);
        *cap = *buf ? nfloats : 0;
    }
    return *buf;
}

static void naive(const float *A, const float *B, float *C, int n)
{
    for (int i = 0; i < n; i++) {
        float *c = C + (size_t)i * n;
        for (int jj = 0; jj < n; jj++) c[jj] = 0.0f;
        for (int k = 0; k < n; k++) {
            float a = A[(size_t)i * n + k];
            const float *b = B + (size_t)k * n;
            for (int jj = 0; jj < n; jj++) c[jj] += a * b[jj];
        }
    }
}

static void choose_tiles(int n, int nt, int *tm, int *tn)
{
    double best = 1e300;
    int bm = 96, bn = 256;
    for (int m = 48; m <= 120; m += MR) {
        for (int w = 4 * NR > 64 ? 4 * NR : 64; w <= 512; w += NR) {
            long tiles = (long)((n + m - 1) / m) * ((n + w - 1) / w);
            long rounds = (tiles + nt - 1) / nt;
            double cost = (double)rounds * m * w * (1.0 + 12.0 / m + 12.0 / w);
            if (cost < best) { best = cost; bm = m; bn = w; }
        }
    }
    *tm = bm;
    *tn = bn;
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    if (g_pool < 0) pool_init();

    int Mp = (n + MR - 1) / MR * MR;
    int Np = (n + NR - 1) / NR * NR;
    float *Ap = ensure(&g_Abuf, &g_Acap, (size_t)Mp * n);
    float *Bp = ensure(&g_Bbuf, &g_Bcap, (size_t)Np * n);
    if (!Ap || !Bp) { naive(A, B, C, n); return; }

    int nt = g_pool + 1;
    if (n < 96) nt = 1;

    int tm, tn;
    if (nt > 1) {
        choose_tiles(n, nt, &tm, &tn);
    } else {
        tm = 96;
        tn = 256;
    }
    int tiles_m = (n + tm - 1) / tm, tiles_n = (n + tn - 1) / tn;
    int ntiles = tiles_m * tiles_n;
    if (nt > ntiles) nt = ntiles;
    if (nt < 1) nt = 1;

    job_t *j = &g_job;
    j->A = A; j->B = B; j->C = C; j->Ap = Ap; j->Bp = Bp;
    j->n = n; j->Mp = Mp; j->Np = Np; j->nt = nt;
    j->tile_m = tm; j->tile_n = tn; j->tiles_n = tiles_n; j->ntiles = ntiles;
    j->next = 0;
    j->bar_count = 0;

    if (nt == 1) {
        run(j, 0);
        return;
    }

    __atomic_store_n(&g_remaining, g_pool, __ATOMIC_RELEASE);
    pthread_mutex_lock(&g_mu);
    __atomic_add_fetch(&g_gen, 1, __ATOMIC_ACQ_REL);
    pthread_cond_broadcast(&g_cv);
    pthread_mutex_unlock(&g_mu);

    run(j, 0);

    while (__atomic_load_n(&g_remaining, __ATOMIC_ACQUIRE) != 0)
        cpu_relax();
}
